-- Action-based access: replace fixed roles with per-user grantable actions.
-- Runs in one transaction (drizzle migrator). Check first: node scripts/db/check-0035.mjs <staging|production>
ALTER TABLE users ADD COLUMN IF NOT EXISTS actions text[] NOT NULL DEFAULT '{}';--> statement-breakpoint
ALTER TABLE users ALTER COLUMN role DROP DEFAULT;--> statement-breakpoint
ALTER TABLE users ALTER COLUMN role TYPE text;--> statement-breakpoint
-- Keep one Tenant Superadmin per tenant (active first, then oldest). Extras become full-access users.
UPDATE users u SET role='tenant_user', actions=ARRAY['dashboard.view','asset.view','asset.create','asset.import','asset.edit','asset.delete','asset.merge','asset.duplicate.dismiss','asset.rescore','asset.inventory.collect','asset.inventory.clear','scan.view','scan.active.run','scan.passive.run','scan.cancel','scan.drift.run','scan.route.view','sbom.view','sbom.download','sbom.scan','sbom.delete','alert.view','alert.manage','alert.bulk_update','advisory.view','advisory.generate','advisory.update','advisory.close_via_chat','cti.view','ti_event.view','ti_event.create','ti_event.edit','ti_event.publish','ti_event.delete','network.view','network.map.run','topology.edit','relationship.view','relationship.manage','relationship.delete','report.view','report.download','report.generate','report.delete','report.snapshot','agent.view','agent.installer.download','agent.enrol','agent.rename','agent.configure','agent.roles.assign','agent.sightings.enable','agent.key.rotate','agent.remove','settings.view','settings.scan_policy.edit','settings.agent_defaults.edit','chatbot.use']::text[] FROM (SELECT user_id, ROW_NUMBER() OVER (PARTITION BY tenant_id ORDER BY is_active DESC, created_at ASC) AS rn FROM users WHERE role='tenant_superadmin' AND tenant_id IS NOT NULL) r WHERE u.user_id = r.user_id AND r.rn > 1;--> statement-breakpoint
-- A Tenant Superadmin with no tenant has nothing to administer.
UPDATE users SET role='tenant_user', actions='{}' WHERE role='tenant_superadmin' AND tenant_id IS NULL;--> statement-breakpoint
UPDATE users SET role='tenant_user', actions=ARRAY['dashboard.view','asset.view','asset.create','asset.import','asset.edit','asset.duplicate.dismiss','asset.rescore','asset.inventory.collect','asset.inventory.clear','scan.view','scan.active.run','scan.passive.run','scan.cancel','scan.drift.run','scan.route.view','sbom.view','sbom.download','sbom.scan','sbom.delete','alert.view','alert.manage','alert.bulk_update','advisory.view','advisory.generate','advisory.update','advisory.close_via_chat','cti.view','ti_event.view','ti_event.create','ti_event.edit','ti_event.publish','ti_event.delete','network.view','network.map.run','topology.edit','relationship.view','relationship.manage','relationship.delete','report.view','report.download','report.generate','report.delete','agent.view','agent.installer.download','agent.enrol','agent.rename','agent.configure','agent.roles.assign','agent.sightings.enable','agent.key.rotate','agent.remove','settings.view','chatbot.use']::text[] WHERE role='tenant_admin';--> statement-breakpoint
UPDATE users SET role='tenant_user', actions=ARRAY['dashboard.view','asset.view','sbom.view','sbom.download','alert.view','advisory.view','cti.view','ti_event.view','network.view','report.view','report.download','agent.view','chatbot.use']::text[] WHERE role='business_owner';--> statement-breakpoint
DROP TYPE IF EXISTS user_role;--> statement-breakpoint
CREATE TYPE user_role AS ENUM ('superadmin','tenant_superadmin','tenant_user');--> statement-breakpoint
ALTER TABLE users ALTER COLUMN role TYPE user_role USING role::user_role;--> statement-breakpoint
ALTER TABLE users ALTER COLUMN role SET DEFAULT 'tenant_user';--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_one_tenant_superadmin ON users (tenant_id) WHERE role = 'tenant_superadmin';
